package com.quincaisoft.sync.application;
import com.quincaisoft.sync.api.SyncService;import com.quincaisoft.sync.infrastructure.*;import com.quincaisoft.sync.domain.DeviceProof;import com.quincaisoft.identity.api.IdentityService;import com.quincaisoft.shared.*;
import com.quincaisoft.audit.api.AuditService;import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.security.access.AccessDeniedException;import tools.jackson.databind.json.JsonMapper;import java.util.*;import java.time.*;import java.security.SecureRandom;import java.util.function.Supplier;
@Service public class DefaultSyncService implements SyncService{
 private final EntityManager em;private final ScopedTransactions tx;private final IdentityService identity;private final JsonMapper json;private final AuditService audit;
 public DefaultSyncService(EntityManager em,ScopedTransactions tx,IdentityService identity,JsonMapper json,AuditService audit){this.em=em;this.tx=tx;this.identity=identity;this.json=json;this.audit=audit;}
 private void owner(){identity.members();}
 private Device view(SyncDevice d){return new Device(d.id,d.epoch,d.actorId,d.name,d.status,d.challenge,d.expiresAt,d.fingerprint,d.version,false);}
 private SyncDevice device(UUID id,boolean lock){var s=TenantContext.current();var d=em.find(SyncDevice.class,new SyncDevice.Key(s.tenantId(),s.companyId(),id),lock?LockModeType.PESSIMISTIC_WRITE:LockModeType.NONE);if(d==null||!d.branchId.equals(s.branchId()))throw new NoSuchElementException("Device not found");return d;}
 public List<Device> devices(){return tx.execute(()->{owner();return em.createQuery("select d from SyncDevice d order by d.name,d.id",SyncDevice.class).getResultList().stream().map(this::view).toList();});}
 public Device challenge(Challenge i){if(i==null||i.operationId()==null||i.name()==null||i.name().isBlank()||i.name().length()>120)throw new IllegalArgumentException("Operation and device name required");var publicKey=DeviceProof.key(i.publicKeyPem());return tx.execute(()->once(i.operationId(),"challenge|"+i,Device.class,()->{var s=TenantContext.current();var d=new SyncDevice();d.tenantId=s.tenantId();d.companyId=s.companyId();d.branchId=s.branchId();d.actorId=s.actorId();d.id=UUID.randomUUID();d.epoch=UUID.randomUUID();d.name=i.name().trim();d.publicKeyPem=i.publicKeyPem();d.fingerprint=DeviceProof.hash(Base64.getEncoder().encodeToString(publicKey.getEncoded()));byte[] nonce=new byte[32];new SecureRandom().nextBytes(nonce);d.challenge=Base64.getUrlEncoder().withoutPadding().encodeToString(nonce);d.expiresAt=Instant.now().plusSeconds(600);d.status="CHALLENGED";em.persist(d);em.flush();audit.append(i.operationId(),"DEVICE_CHALLENGED","DEVICE",d.id,"Enrollment challenge requested");return view(d);}));}
 public Device prove(UUID id,Proof i){if(i==null||i.operationId()==null||i.signatureBase64()==null)throw new IllegalArgumentException("Proof required");return tx.execute(()->once(i.operationId(),"prove|"+id+"|"+i,Device.class,()->{var d=device(id,true);if(!d.actorId.equals(TenantContext.current().actorId()))throw new AccessDeniedException("Enrollment belongs to another actor");if(d.version!=i.version())throw new RevisionConflict("Device changed");if(!d.status.equals("CHALLENGED")||d.expiresAt.isBefore(Instant.now()))throw new IllegalStateException("Enrollment challenge expired or already used");DeviceProof.verify(d.publicKeyPem,DeviceProof.enrollment(d.tenantId,d.companyId,d.branchId,d.id,d.epoch,d.challenge),i.signatureBase64());d.status="PROVED";d.version++;em.flush();audit.append(i.operationId(),"DEVICE_PROVED","DEVICE",d.id,"Device key possession verified");return view(d);}));}
 public Device approve(UUID id,Approval i){if(i==null||i.operationId()==null||i.reason()==null||i.reason().trim().length()<3||i.reason().length()>2000)throw new IllegalArgumentException("Approval operation and reason required");return tx.execute(()->{owner();return once(i.operationId(),"approve|"+id+"|"+i,Device.class,()->{var d=device(id,true);if(d.version!=i.version())throw new RevisionConflict("Device changed");if(!d.status.equals("PROVED"))throw new IllegalStateException("Proof of device key required");d.status="ACTIVE";d.approvedBy=TenantContext.current().actorId();d.approvalReason=i.reason();d.version++;em.flush();audit.append(i.operationId(),"DEVICE_APPROVED","DEVICE",d.id,i.reason());return view(d);});});}
 public Receipt recover(Recovery i){if(i==null||i.operationId()==null||i.sourceOperationId()==null||i.deviceId()==null||i.deviceEpoch()==null||i.sequence()<1||i.sequence()>9007199254740991L||i.signatureBase64()==null||i.signatureBase64().length()>2048||i.classification()==null||!Set.of("COMPLETED_AUTHORIZED","COMPLETED_EXCEPTION").contains(i.classification())||i.payloadJson()==null||i.payloadJson().length()>250000||i.reason()==null||i.reason().trim().length()<3||i.reason().length()>2000)throw new IllegalArgumentException("Bounded completed-evidence envelope and owner reason required");json.readTree(i.payloadJson());return tx.execute(()->{owner();return once(i.operationId(),"recover|"+i,Receipt.class,()->{var d=device(i.deviceId(),true);if(!d.epoch.equals(i.deviceEpoch())||d.status.equals("CHALLENGED"))throw new IllegalStateException("Known proved device epoch required");var hash=DeviceProof.hash(i.payloadJson());DeviceProof.verify(d.publicKeyPem,DeviceProof.recovery(d.tenantId,d.companyId,d.branchId,d.id,d.epoch,i.sequence(),i.sourceOperationId(),i.classification(),hash),i.signatureBase64());var previous=em.createQuery("select r from RecoveryEvidence r where r.deviceId=:d and r.deviceEpoch=:e and (r.deviceSequence=:s or r.sourceOperationId=:o)",RecoveryEvidence.class).setParameter("d",d.id).setParameter("e",d.epoch).setParameter("s",i.sequence()).setParameter("o",i.sourceOperationId()).getResultList();var r=new RecoveryEvidence();r.tenantId=d.tenantId;r.companyId=d.companyId;r.branchId=d.branchId;r.id=UUID.randomUUID();r.operationId=i.operationId();r.sourceOperationId=i.sourceOperationId();r.deviceId=d.id;r.deviceEpoch=d.epoch;r.deviceSequence=i.sequence();r.classification=i.classification();r.payloadJson=i.payloadJson();r.payloadHash=hash;r.signatureBase64=i.signatureBase64();r.reason=i.reason();r.ownerId=TenantContext.current().actorId();r.receivedAt=Instant.now();r.status=previous.stream().anyMatch(old->!old.payloadHash.equals(hash)||!old.classification.equals(i.classification())||old.deviceSequence!=i.sequence()||!old.sourceOperationId.equals(i.sourceOperationId()))?"CONFLICTING_HISTORY":"REVIEW_REQUIRED";em.persist(r);em.flush();audit.append(i.operationId(),"RECOVERY_"+r.status,"RECOVERY_EVIDENCE",r.id,i.reason());return receipt(r);});});}
 private Receipt receipt(RecoveryEvidence r){return new Receipt(r.id,r.sourceOperationId,r.status,r.payloadHash,r.receivedAt,false);}
 public List<Receipt> recovery(){return tx.execute(()->{owner();return em.createQuery("select r from RecoveryEvidence r order by r.receivedAt desc,r.id",RecoveryEvidence.class).setMaxResults(100).getResultList().stream().map(this::receipt).toList();});}
 public Operation status(UUID operation){return tx.execute(()->{identity.current();var s=TenantContext.current();var rows=em.createNativeQuery("select status,source_type,source_id,created_at,actor_id from idempotency_result where tenant_id=:t and company_id=:c and branch_id=:b and operation_id=:o").setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",operation).getResultList();if(rows.isEmpty())throw new NoSuchElementException("Operation not found");Object[] row=(Object[])rows.getFirst();if(!s.actorId().equals(row[4]))throw new NoSuchElementException("Operation not found");return new Operation(operation,(String)row[0],(String)row[1],(UUID)row[2],timestamp(row[3]));});}
 private static Instant timestamp(Object value){return switch(value){case Instant instant->instant;case OffsetDateTime offset->offset.toInstant();case java.sql.Timestamp stamp->stamp.toInstant();default->throw new IllegalStateException("Unsupported operation timestamp");};}
 private <T>T once(UUID operation,String material,Class<T> type,Supplier<T> action){identity.current();var s=TenantContext.current();String hash=DeviceProof.hash(material);em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:key,0))").setParameter("key",s.tenantId()+":"+operation).getSingleResult();var rows=em.createNativeQuery("select request_hash,response_json::text,company_id,branch_id,actor_id,source_type,status from idempotency_result where tenant_id=:t and operation_id=:o").setParameter("t",s.tenantId()).setParameter("o",operation).getResultList();if(!rows.isEmpty()){Object[] row=(Object[])rows.getFirst();if(!hash.equals(row[0])||!s.companyId().equals(row[2])||!s.branchId().equals(row[3])||!s.actorId().equals(row[4])||!"SYNC".equals(row[5])||!"ACCEPTED".equals(row[6]))throw new IllegalStateException("Operation ID belongs to another request or actor");if(row[1]==null)throw new IllegalStateException("Receipt expired; reconcile original operation");return json.readValue((String)row[1],type);}T result=action.get();UUID source=result instanceof Device d?d.id():((Receipt)result).evidenceId();em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json)values(:t,:o,:c,:b,:h,'SYNC',:id,cast(:response as jsonb))").setParameter("t",s.tenantId()).setParameter("o",operation).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",hash).setParameter("id",source).setParameter("response",json.writeValueAsString(result)).executeUpdate();return result;}
}
